func (this *Btcturk) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	//   {
	//     "pair": "BTCTRY",
	//     "pairNormalized": "BTC_TRY",
	//     "timestamp": 1618826361234,
	//     "last": 462485,
	//     "high": 473976,
	//     "low": 444201,
	//     "bid": 461928,
	//     "ask": 462485,
	//     "open": 456915,
	//     "volume": 917.41368645,
	//     "average": 462868.29574589,
	//     "daily": 5570,
	//     "dailyPercent": 1.22,
	//     "denominatorSymbol": "TRY",
	//     "numeratorSymbol": "BTC",
	//     "order": 1000
	//   }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(ticker, "pair")
	market = this.SafeMarket(marketId, market)
	var symbol any = GetValue(market, "symbol")
	var timestamp any = this.SafeInteger(ticker, "timestamp")
	var last any = this.SafeString(ticker, "last")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open"),
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        this.SafeString(ticker, "daily"),
		"percentage":    this.SafeString(ticker, "dailyPercent"),
		"average":       this.SafeString(ticker, "average"),
		"baseVolume":    this.SafeString(ticker, "volume"),
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

